css:
/* Rider Islands. Values come from Rider 2026.2: themes/islands/ManyIslandsDark|Light.theme.json
   and colorSchemes/RiderIslandsDark.xml. Island.arc 20 = 10px radius, Island.borderWidth 6 = 6px gap,
   Component.arc 8 = 4px radius. Islands have no outline and no shadow: the frame is the separator. */
:root{--isl-gap:6px;--isl-arc:10px;--isl-frame:#E9EAEE;--isl-bg:#FFFFFF;--isl-hover:#00000012;--isl-press:#00000020;--isl-row-hover:#0000000D;--isl-popup:#FFFFFF;--isl-popup-line:#D1D3D9;--isl-tip:#FFFFFF;--isl-tip-line:#D1D3D9;--isl-tip-text:#000000;--isl-line:#E9EAEE;--isl-shadow:#00000026;--isl-success:#338555;--isl-accent:#3871E1;--isl-glow:radial-gradient(ellipse 620px 220px at 6% -50px,#3871E12E,#3871E100 70%)}
.dark{--isl-frame:#26282C;--isl-bg:#191A1C;--isl-hover:#FFFFFF17;--isl-press:#FFFFFF29;--isl-row-hover:#FFFFFF10;--isl-popup:#26282C;--isl-popup-line:#33353B;--isl-tip:#33353B;--isl-tip-line:#33353B;--isl-tip-text:#D1D3D9;--isl-line:#26282C;--isl-shadow:#00000066;--isl-success:#6DB083;--isl-glow:radial-gradient(ellipse 620px 220px at 6% -50px,#3F448D66,#3F448D00 70%)}

/* Frame: MainWindow.background. Toolbars sit on it directly, as in the IDE. */
html,body{background-color:var(--isl-frame)!important}
body{font-family:"Inter Variable",Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",system-ui,sans-serif;-webkit-font-smoothing:antialiased}
[data-slot=sidebar-wrapper]{background:var(--isl-glow) no-repeat,var(--isl-frame)!important}
[data-slot=sidebar-container],[data-slot=sidebar-inner]{background:transparent!important;border:0!important;box-shadow:none!important}
main[data-slot=sidebar-inset]:has([data-chat-column]>[data-chat-header]),div:has(>[data-chat-column]>[data-chat-header]),[data-chat-column]:has(>[data-chat-header]),[data-chat-header]{background:transparent!important}
[data-chat-header]{border:0!important;box-shadow:none!important}

/* Islands: thread list, conversation, terminal, side panel. */
[data-slot=sidebar-inner] :has(>[data-slot=scroll-area-viewport]>[data-slot=sidebar-content]){background:var(--isl-bg)!important;border-radius:var(--isl-arc)!important;margin:0 0 var(--isl-gap) var(--isl-gap)!important;width:calc(100% - var(--isl-gap))!important;overflow:hidden!important}
[data-chat-column]>[data-chat-header]+div{background:var(--isl-bg)!important;border-radius:var(--isl-arc)!important;margin:0 var(--isl-gap) var(--isl-gap)!important;overflow:hidden!important}
[data-thread-terminal-drawer][data-terminal-owner=drawer]{margin:0 var(--isl-gap) var(--isl-gap)!important;border:0!important;border-radius:var(--isl-arc)!important;box-shadow:none!important}
/* The side panel keeps its box; a frame-coloured border makes the gap (Island.borderWidth). */
[data-workspace-area=panel]{border:solid transparent!important;border-width:var(--isl-gap) var(--isl-gap) var(--isl-gap) 0!important;border-radius:10px 16px 16px 10px/16px!important;background-color:var(--isl-bg)!important;background-clip:padding-box!important;overflow:hidden!important;box-shadow:none!important}
[data-thread-details-card]{border:1px solid var(--isl-popup-line)!important;border-radius:8px!important;box-shadow:0 8px 24px var(--isl-shadow)!important}

/* Toolbar buttons: flat, grey hover (ActionButton.hoverBackground). */
html[data-theme-id] [data-chat-header] :is([data-slot=button],[data-slot=menu-trigger],[data-toolbar-control]){background-color:transparent!important;border-color:transparent!important;box-shadow:none!important;border-radius:6px!important}
html[data-theme-id] [data-chat-header] :is([data-slot=button],[data-slot=menu-trigger],[data-toolbar-control]):is(:hover,[data-pressed]){background-color:var(--isl-hover)!important}
html[data-theme-id] [data-chat-header] :is([data-slot=button],[data-slot=menu-trigger],[data-toolbar-control]):active{background-color:var(--isl-press)!important}

/* Tree rows: Tree.hoverBackground, selection-bg-active, no accent bar. */
html[data-theme-id] [data-app-sidebar]{--sidebar-row-hover:var(--isl-row-hover)!important}
[data-thread-item],[data-sidebar-row]{border-radius:6px!important}
[data-slot=project-monogram]{border-radius:4px!important}

/* Controls: Component.arc / Button.arc. */
[data-slot=button],[data-slot=input],[data-slot=select-trigger]{border-radius:4px!important}
[data-slot=button]:focus-visible,[data-slot=input]:focus-visible,[data-slot=select-trigger]:focus-visible{outline:2px solid var(--isl-accent)!important;outline-offset:1px!important}
svg.lucide{stroke-width:1.5}

/* Chat input and messages, inside the editor island. */
[data-slot=composer-host]{border-radius:var(--isl-arc)!important;box-shadow:none!important}
[data-slot=composer-host]::before,[data-slot=composer-host]::after,[data-chat-composer-main-surface]{border-radius:var(--isl-arc)!important}
[data-user-message-bubble]{border-radius:var(--isl-arc)!important;box-shadow:none!important}
.chat-markdown-codeblock{border-radius:6px!important}
.chat-markdown code,.chat-markdown pre,.chat-markdown-codeblock,.composer-tiptap code{font-family:"JetBrains Mono",ui-monospace,"SF Mono",Menlo,Consolas,monospace!important}

/* Popups: Popup.background + Popup.borderColor. Tooltips: ToolTip.background. */
[data-slot=menu-popup],[data-slot=popover-popup],[data-slot=dialog-popup]{background-color:var(--isl-popup)!important;border:1px solid var(--isl-popup-line)!important;box-shadow:0 8px 24px var(--isl-shadow)!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
[data-slot=menu-popup],[data-slot=popover-popup]{border-radius:8px!important}
[data-slot=dialog-popup]{border-radius:var(--isl-arc)!important}
[data-slot=tooltip-popup]{background-color:var(--isl-tip)!important;color:var(--isl-tip-text)!important;border:1px solid var(--isl-tip-line)!important;border-radius:6px!important;box-shadow:0 4px 12px var(--isl-shadow)!important}

/* Scrollbars: ScrollBar.thumbColor / hoverThumbColor. */
html[data-theme-id]{--app-scrollbar-thumb:#80808059!important;--app-scrollbar-thumb-hover:#8080808C!important}
[data-slot=scroll-area-thumb]{border-radius:4px!important}
::-webkit-scrollbar-thumb{background-color:#80808059;border-radius:4px}
::-webkit-scrollbar-thumb:hover{background-color:#8080808C}

/* Sidebar sections: Recents on top, status shelves together at the bottom. */
ul:has(>li[data-thread-item]){display:flex!important;flex-direction:column!important}
ul:has(>li[data-thread-item])::before{content:'Recents';display:block;order:0;padding:8px 10px 4px;color:var(--sidebar-muted-foreground);font-size:12px;font-weight:600}
[data-testid*=working-h]{order:10!important;margin-top:4px!important;margin-bottom:4px!important}
[data-testid*=working-h]~:not([data-testid*=snoozed-h],[data-testid*=settled-h],[data-testid*=snoozed-h]~*,[data-testid*=settled-h]~*){order:11!important}
:is([data-testid*=snoozed-h],[data-testid*=settled-h]){margin-top:4px!important}
[data-testid*=snoozed-h]{margin-top:auto!important}
ul:not(:has(>[data-testid*=snoozed-h]))>[data-testid*=settled-h]{margin-top:auto!important}
ul:not(:has(>[data-testid*=snoozed-h],>[data-testid*=settled-h]))>[data-testid*=working-h]{margin-top:auto!important}
[data-testid$=-shelf-toggle]{border-radius:6px!important;font-size:12px!important}
[data-thread-item]:is(:has([data-sidebar-parent='shelf:settled']),:has([data-sidebar-row][aria-label*=', Done'])) .text-sm{color:var(--isl-success)!important}
